import Foundation
import AppKit

public enum TextureImageStore {
    private static let textureData: [String: String] = [
        "paper_2": "",
        "paper_3": "",
        "paper_4": "",
        "paper_5": "",
        "paper_6": "",
        "paper_7": "",
        "paper_8": "",
        "grit_1": "",
        "grit_2": "",
        "grit_3": "",
        "film_2": "",
        "film_3": "",
        "film_4": "",
        "film_6": "",
        "halftone_3": "",
        "halftone_4": "",
        "halftone_6": "",
        "halftone_8": "",
        "plastic_1": "",
        "plastic_2": "",
        "plastic_3": "",
        "plastic_4": "",
    ]

    public static func getBase64(for key: String) -> String? {
        return textureData[key]
    }

    public static func getImage(for key: String) -> NSImage? {
        guard let b64 = textureData[key], let data = Data(base64Encoded: b64) else { return nil }
        return NSImage(data: data)
    }
}
